import cPickle


def K(x):
    return x


def load(data):
    try:
        value = cPickle.loads(K(data))
    except Exception as e:
        return ('error', type(e).__name__, str(e))
    if type(value) is object:
        return ('object',)
    return (type(value).__name__, value)


